// Build one Telegram digest of leads whose last_seen is within the last 24 hours.
const HOURS = 24;
const MAX_LIST = 25; // per tier, keeps the message under Telegram's 4096-char limit
const cutoff = Date.now() - HOURS * 60 * 60 * 1000;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => String(r.contact_id ?? '').trim() !== '')
  .filter((r) => {
    const t = new Date(String(r.last_seen ?? '').trim()).getTime();
    return !isNaN(t) && t >= cutoff;
  });

const byTier = { hot: [], warm: [], cold: [] };
for (const r of rows) {
  const tier = String(r.tier || '').toLowerCase();
  (byTier[tier] || byTier.cold).push(r);
}

const today = new Date().toLocaleDateString('en-GB', { timeZone: 'Asia/Dhaka', day: 'numeric', month: 'short', year: 'numeric' });
let text;
if (!rows.length) {
  text = `📭 <b>Daily lead digest</b> — ${esc(today)}\nNo new leads in the last ${HOURS}h.`;
} else {
  const line = (r) => {
    const name = [r.first_name, r.last_name].filter(Boolean).join(' ') || r.email || r.phone || r.contact_id;
    const contact = r.phone || r.email || '';
    const repeat = Number(r.submission_count) > 1 ? ` 🔁${Number(r.submission_count)}` : '';
    return `• ${esc(name)} (${esc(r.score)})${contact ? ' — ' + esc(contact) : ''}${repeat}`;
  };
  const section = (title, list) => {
    if (!list.length) return [];
    const shown = list.sort((x, y) => Number(y.score) - Number(x.score)).slice(0, MAX_LIST).map(line);
    if (list.length > MAX_LIST) shown.push(`…and ${list.length - MAX_LIST} more`);
    return ['', `<b>${title}</b>`, ...shown];
  };
  text = [
    `📊 <b>Daily lead digest</b> — ${esc(today)} (last ${HOURS}h)`,
    `Total: <b>${rows.length}</b> | 🔥 Hot: <b>${byTier.hot.length}</b> | 🌤 Warm: <b>${byTier.warm.length}</b> | ❄️ Cold: <b>${byTier.cold.length}</b>`,
    byTier.hot.length ? '(Hot leads were alerted instantly.)' : '',
    ...section('🌤 Warm', byTier.warm),
    ...section('❄️ Cold', byTier.cold),
  ].filter((l, i) => l !== '' || i > 2).join('\n');
  if (text.length > 4000) text = text.slice(0, 3990) + '\n…';
}

return [{ json: { text, total: rows.length, hot: byTier.hot.length, warm: byTier.warm.length, cold: byTier.cold.length } }];
